import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityManager;
import net.minecraftforge.common.capabilities.CapabilityToken;
import net.minecraftforge.common.capabilities.ICapabilityProvider;
import net.minecraftforge.common.util.INBTSerializable;
import net.minecraftforge.common.util.LazyOptional;

public class AnimalCareProvider
implements ICapabilityProvider,
INBTSerializable<CompoundTag> {
    public static Capability<AnimalCare> CARE = CapabilityManager.get((CapabilityToken)new CapabilityToken<AnimalCare>(){});
    private AnimalCare AnimalCare = null;
    private final LazyOptional<AnimalCare> opt = LazyOptional.of(this::createAnimalCare);

    @Nonnull
    private AnimalCare createAnimalCare() {
        if (this.AnimalCare == null) {
            this.AnimalCare = new AnimalCare();
        }
        return this.AnimalCare;
    }

    @Nonnull
    public <T> LazyOptional<T> getCapability(@Nonnull Capability<T> cap) {
        if (cap == CARE) {
            return this.opt.cast();
        }
        return LazyOptional.empty();
    }

    @Nonnull
    public <T> LazyOptional<T> getCapability(@Nonnull Capability<T> cap, @Nullable Direction side) {
        return this.getCapability(cap);
    }

    public CompoundTag serializeNBT() {
        CompoundTag nbt = new CompoundTag();
        this.createAnimalCare().saveNBTData(nbt);
        return nbt;
    }

    public void deserializeNBT(CompoundTag nbt) {
        this.createAnimalCare().loadNBTData(nbt);
    }
}

